BEGIN;

-- Canonical parties for the existing preview. Sensitive private identifiers are intentionally absent.
ON CONFLICT (id) DO UPDATE SET display_name=EXCLUDED.display_name,lifecycle_status='active';

ON CONFLICT (tenant_id,party_id) DO UPDATE SET first_name=EXCLUDED.first_name,last_name=EXCLUDED.last_name;

ON CONFLICT (tenant_id,party_id) DO UPDATE SET legal_name=EXCLUDED.legal_name,registration_number=EXCLUDED.registration_number,contact_person=EXCLUDED.contact_person;

ON CONFLICT (id) DO UPDATE SET value=EXCLUDED.value,normalized_value=EXCLUDED.normalized_value,is_primary=EXCLUDED.is_primary;

ON CONFLICT (id) DO UPDATE SET line1=EXCLUDED.line1,city=EXCLUDED.city,postal_code=EXCLUDED.postal_code;

SELECT ('c3000000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY id)::text,12,'0'))::uuid,tenant_id,id,'preview-crm','client-'||row_number() OVER (ORDER BY id)
FROM parties WHERE tenant_id='d0000000-0000-4000-8000-000000000001'
ON CONFLICT (id) DO NOTHING;

SELECT ('c4000000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY project_id,party_id)::text,12,'0'))::uuid,
 'd0000000-0000-4000-8000-000000000001',project_id,party_id,relationship_type
FROM (VALUES
 ('e0000000-0000-4000-8000-000000000001'::uuid,'c0000000-0000-4000-8000-000000000001'::uuid,'buyer'),
 ('e0000000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000002','buyer'),
 ('e0000000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000003','buyer'),
 ('e0000000-0000-4000-8000-000000000003','c0000000-0000-4000-8000-000000000003','prospect'),
 ('e0000000-0000-4000-8000-000000000002','c0000000-0000-4000-8000-000000000004','buyer'),
 ('e0000000-0000-4000-8000-000000000002','c0000000-0000-4000-8000-000000000005','buyer'),
 ('e0000000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000006','prospect'),
 ('e0000000-0000-4000-8000-000000000002','c0000000-0000-4000-8000-000000000006','buyer'),
 ('e0000000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000007','buyer'),
 ('e0000000-0000-4000-8000-000000000002','c0000000-0000-4000-8000-000000000008','owner'),
 ('e0000000-0000-4000-8000-000000000001','c0000000-0000-4000-8000-000000000009','prospect'),
 ('e0000000-0000-4000-8000-000000000003','c0000000-0000-4000-8000-000000000010','prospect'),
 ('e0000000-0000-4000-8000-000000000002','c0000000-0000-4000-8000-000000000011','prospect'),
 ('e0000000-0000-4000-8000-000000000003','c0000000-0000-4000-8000-000000000011','prospect')
) link(project_id,party_id,relationship_type)
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO UPDATE SET status=EXCLUDED.status,last_interest_at=EXCLUDED.last_interest_at;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

SELECT ('c9000000-0000-4000-8000-'||lpad(row_number() OVER (ORDER BY id)::text,12,'0'))::uuid,tenant_id,project_id,id,NULL,current_stage,'seed','Výchozí obchodní etapa preview',opened_at,'d3000000-0000-4000-8000-000000000001'
FROM sales_cases WHERE tenant_id='d0000000-0000-4000-8000-000000000001'
ON CONFLICT (id) DO NOTHING;

ON CONFLICT (id) DO NOTHING;

COMMIT;
